settings.custom_liquid:
{%- comment -%}
  Product Breadcrumb (hardcoded tow-wire parent + metafield collection)
  Structure:
  Tow wire protection / {{ collection from metafield }} / {{ product.title }}

  - No "Category" label
  - Hardcoded parent: /collections/tow-wire-protectors + "Tow wire protection"
  - Uses product.metafields.custom.collectie (Collection reference)
  - JSON-LD included
{%- endcomment -%}

{%- assign bc_col = product.metafields.custom.collectie.value -%}

{%- if bc_col != blank -%}
  <div class="breadcrumbs-wrap">
    <nav class="breadcrumbs" aria-label="Breadcrumb">
      <ol class="breadcrumbs__list" role="list">

        <!-- Hardcoded parent -->
        <li class="breadcrumbs__item">
          <a class="breadcrumbs__link" href="/collections/tow-wire-protectors">
            Tow wire protection
          </a>
        </li>

        <li class="breadcrumbs__item" aria-hidden="true">/</li>

        <!-- Metafield collection -->
        <li class="breadcrumbs__item">
          <a class="breadcrumbs__link" href="{{ bc_col.url }}">
            {{ bc_col.title }}
          </a>
        </li>

        <li class="breadcrumbs__item" aria-hidden="true">/</li>

        <!-- Current product -->
        <li class="breadcrumbs__item">
          <span class="breadcrumbs__current" aria-current="page">
            {{ product.title }}
          </span>
        </li>

      </ol>
    </nav>
  </div>

  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    "itemListElement": [
      {
        "@type": "ListItem",
        "position": 1,
        "name": "Tow wire protection",
        "item": "{{ shop.url }}/collections/tow-wire-protectors"
      },
      {
        "@type": "ListItem",
        "position": 2,
        "name": {{ bc_col.title | json }},
        "item": "{{ shop.url }}{{ bc_col.url }}"
      },
      {
        "@type": "ListItem",
        "position": 3,
        "name": {{ product.title | json }},
        "item": "{{ shop.url }}{{ product.url }}"
      }
    ]
  }
  </script>

  <style>
    .breadcrumbs-wrap {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0;
    }

    @media screen and (max-width: 749px) {
      .breadcrumbs-wrap {
        padding-left: 2rem;
        padding-right: 2rem;
      }
    }

    .breadcrumbs {
      margin: 0;
      padding: 0;
      font-family: inherit;
      font-size: 16px;
      font-weight: 400;
      line-height: 1.2;
      color: #BF1E2D;
    }

    .breadcrumbs__list {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 0;
      margin: 0;
      list-style: none;
      flex-wrap: wrap;
    }

    .breadcrumbs__link {
      color: #BF1E2D;
      text-decoration: none;
    }

    .breadcrumbs__link:hover {
      text-decoration: underline;
    }

    .breadcrumbs__current {
      color: #BF1E2D;
      font-size: 16px;
      font-weight: 400;
    }
  </style>
{%- endif -%}
